def transform(grid):
    n=len(grid)
    out=[[0]*(2*n) for _ in range(2*n)]
    for r in range(n):
        for c in range(n):
            out[r][c]=grid[r][c]
            out[r][n+c]=grid[n-1-c][r]
            out[n+r][c]=grid[c][n-1-r]
            out[n+r][n+c]=grid[n-1-r][n-1-c]
    return out
